mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 1.0;
  vec3 q = p;
  q.z = mod(q.z, 2.0) - 1.0;
  float rib = length(vec2(length(q.xy) - 1.5, q.z)) - 0.16;
  float wall = 1.6 - length(p.xy);
  return min(rib, wall);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 14.0) break;
    t += d * 0.8;
  }
  vec3 col = glow * vec3(0.2, 0.9, 0.4) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
